          [
            "10. Material (made of?)",
            "Chất liệu",
            "stone, plastic, steel, paper, leather..."
          ],
          [
            "11. Type (what kind?)",
            "Chủng loại",
            "an electric kettle, political matters..."
          ],
          [
            "12. Purpose (what for?)",
            "Mục đích sử dụng",
            "a bread knife, walking stick, riding boots, bath towel..."
          ]
